<script lang="ts">
 let { data,form }=$props();
 function href(id:string){return `/${data.tenantSlug}/app/functions/f01/strategic-review?meeting=${encodeURIComponent(id)}`;}
</script>
<svelte:head><title>Strategic Review · NuBlox</title></svelte:head>
<div class="page">
<nav class="breadcrumb"><a href={`/${data.tenantSlug}/app/functions/f01`}>F01 Strategy & Enterprise Planning</a><span>›</span><strong>F01.07 Strategic Review</strong></nav>
<header class="hero section-card"><div><span class="eyebrow">F01.07 · AGG-02-GOVERNANCE-MEETING</span><h1>Strategic review</h1><p>Run attributable governance reviews with quorum, agenda, findings and next-cycle evidence while keeping resulting Decisions and Actions in their shared authoritative aggregates.</p></div><div class="principle"><strong>Review ≠ Decision ≠ Action</strong><span>The meeting owns the governance occurrence and evidence.</span><small>Choices are immutable Decisions; follow-up execution is shared Work.</small></div></header>
{#if form?.message}<div class="message">{form.message}</div>{/if}
<div class="workspace">
<aside class="section-card register">
