 {#if data.capabilities.canManage}<details class="command"><summary>Schedule review</summary><form method="POST" action="?/create"><label>Reference<input name="meetingRef" required/></label><div class="grid"><label>Context type<input name="governanceContextType" required value="STRATEGY"/></label><label>Context ID<input name="governanceContextId" required/></label><label>Scheduled at<input name="scheduledAt" type="datetime-local" required/></label><label>Quorum<input name="quorumRequired" type="number" min="1" value="1" required/></label></div><label>Location / channel<input name="locationChannel"/></label><label>Attendees<textarea name="attendees" rows="5" required></textarea><small>Party ID | CHAIR/MEMBER/SECRETARY/OBSERVER</small></label><label>Agenda<textarea name="agenda" rows="7" required></textarea><small>Subject | REVIEW/DECISION | Purpose | Subject type | Subject ID | Subject version</small></label><button>Schedule strategic review</button></form></details>{/if}
</aside>
