 <section><span class="eyebrow">Agenda</span><div class="rows">{#each data.agendaRows as row}<article><div><strong>{row.itemNo}. {row.subject}</strong><span>{row.requiredOutcome}</span></div><p>{row.purpose}</p><small>{row.subjectType??'General'} · {row.subjectId??'—'} · {row.status}</small></article>{/each}</div></section></div>

