 <details class="command"><summary>Complete review</summary><form method="POST" action="?/complete"><input type="hidden" name="meetingId" value={data.selected.id}/><input type="hidden" name="aggregateVersion" value={data.selected.aggregateVersion}/><label>Minutes summary<textarea name="minutesSummary" rows="4" required></textarea></label><label>Next review<input name="nextReviewAt" type="datetime-local"/></label><button>Complete review</button></form></details>
 {/if}
</section>
<section class="section-card panel"><span class="eyebrow">Review findings</span><h2>{data.findings.length} findings</h2><div class="rows">{#each data.findings as finding}<article><div><strong>{finding.findingType}</strong><span>{finding.subjectType}</span></div><p>{finding.finding}</p><small>{finding.recommendation}</small></article>{:else}<p class="empty">No findings recorded.</p>{/each}</div></section>
{:else}<section class="section-card empty-state"><h2>Schedule the first Strategic Review</h2><p>Bring strategy, assumptions and performance evidence into a governed review occurrence.</p></section>{/if}
</main>
</div>
</div>
